import unreal, json
actors=unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors()
target_y={'MallEscalator_Up':550,'MallEscalator_Down':800,'Escalator_LowerLanding':675,'Escalator_UpperLanding':675,'Escalator_UpperBackGuard':675,'Escalator_UpperLeftGuard':370,'Escalator_UpperRightGuard':980,'Escalator_SupportA':400,'Escalator_SupportB':400,'Escalator_SupportC':950,'Escalator_SupportD':950}
found={}
with unreal.ScopedEditorTransaction('Clear mall escalator approach area'):
    for actor in actors:
        label=actor.get_actor_label()
        if label in target_y:
            position=actor.get_actor_location()
            actor.set_actor_location(unreal.Vector(position.x,target_y[label],position.z),False,False)
            if abs(actor.get_actor_location().y-target_y[label])>0.1: raise RuntimeError('Could not move '+label)
            found[label]=actor
if set(found)!=set(target_y): raise RuntimeError('Escalator actor missing')
if not unreal.get_editor_subsystem(unreal.LevelEditorSubsystem).save_current_level(): raise RuntimeError('Could not save level')
print(json.dumps({'saved':True,'up_origin':[1100,550,6],'down_origin':[1100,800,6],'dirty_content':[p.get_path_name() for p in unreal.EditorLoadingAndSavingUtils.get_dirty_content_packages()],'dirty_maps':[p.get_path_name() for p in unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages()]}))
